<?php require_once '../includes/auth.php';admin_required();$pending=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE moderation_status='pending'")->fetchColumn();$flagged=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE moderation_status='flagged'")->fetchColumn();$sellers=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='seller' AND account_status='active'")->fetchColumn();$suspended=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='seller' AND account_status='suspended'")->fetchColumn();$title='Admin';require '../includes/header.php';?><h1>Admin</h1><p class="text-muted">Platform management and moderation.</p><div class="row g-3 mb-4"><div class="col-md-3"><div class="card"><div class="card-body"><h5>Pending products</h5><div class="display-6"><?=e($pending)?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><h5>Flagged products</h5><div class="display-6"><?=e($flagged)?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><h5>Active sellers</h5><div class="display-6"><?=e($sellers)?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><h5>Suspended sellers</h5><div class="display-6"><?=e($suspended)?></div></div></div></div></div><a class="btn btn-warning" href="/admin/products.php">Review products</a> <a class="btn btn-outline-success" href="/admin/users.php">Manage sellers</a> <a class="btn btn-outline-secondary" href="/admin/audit-log.php">Audit log</a><?php require '../includes/footer.php';?>